contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 v) public payable {
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.withdraw(v); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            (reverted && address(c).balance == balanceBefore && depositsBefore == c.depositsCount()) ||
            (!reverted && address(c).balance + v == balanceBefore && depositsBefore == c.depositsCount())
        );
    }

    receive() external payable {}
}

